UPDATE races r SET event_schedule = jsonb_set(event_schedule, '{victory_type}', to_jsonb(CASE WHEN cr.second_place_delta > 5 THEN 'dominant' ELSE 'normal' END))
FROM (SELECT matchref as rak_id, MIN(scoreval) FILTER (WHERE scoreval > 0) as second_place_delta FROM constructor_results GROUP BY matchref) cr
WHERE r.rak_id = cr.rak_id;

